css:
.cpf { direction: rtl; font-family: 'Noto Sans Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; color: #000; font-size: 11px; line-height: 1.6; }
.cpf table { width: 100%; border-collapse: collapse; }
.cpf .h { text-align: center; border-bottom: 1.5px solid #000; padding-bottom: 2mm; margin-bottom: 3mm; }
.cpf .h .co { font-size: 14px; font-weight: bold; }
.cpf .h .t { font-size: 13px; font-weight: bold; margin-top: 1mm; }
.cpf .h .m { font-size: 10px; margin-top: 0.5mm; }
.cpf .meta th, .cpf .meta td { border: 1px solid #000; padding: 1.5mm 2.5mm; text-align: right; vertical-align: middle; word-wrap: break-word; }
.cpf .meta th { width: 16%; font-weight: bold; white-space: nowrap; }
.cpf .amt { border: 1px solid #000; margin-top: 3mm; padding: 2mm; text-align: center; font-size: 13px; font-weight: bold; }
.cpf .words { text-align: center; font-size: 10.5px; margin-top: 1.5mm; }
.cpf .sign { margin-top: 12mm; }
.cpf .sign td { width: 33%; text-align: center; border: none; padding: 0 6mm; font-weight: bold; }
.cpf .sign .l { border-bottom: 1px solid #000; height: 9mm; margin-bottom: 1.5mm; }
